int vinit(void){struct vr*r=q.response;f=0;if(!r||!r->frames)return 0;for(u64 i=0;i<r->count;++i){struct vf*x=r->frames[i];if(x&&x->address&&x->width>=2&&x->width<=UINT32_MAX/4u&&x->height>=2&&x->height<=UINT32_MAX&&x->pitch<=UINT32_MAX&&x->pitch>=x->width*4&&x->bpp==32&&x->model==1&&x->rs==8&&x->ro==16&&x->gs==8&&x->go==8&&x->bs==8&&!x->bo){f=x;return 1;}}return 0;}void vinfo(struct vinfo*v){v->size=sizeof(*v);v->width=(u32)f->width;v->height=(u32)f->height;v->pitch=(u32)f->pitch;v->format=1;v->reserved[0]=v->reserved[1]=v->reserved[2]=0;}u8*vtarget(u32 x,u32 y,u32 w,u32 h,u32*pitch){if(!f||!w||!h||x>=f->width||y>=f->height||w>f->width-x||h>f->height-y)return 0;*pitch=(u32)f->pitch;return(u8*)f->address+(u64)y*f->pitch+(u64)x*4;}
